-- Engangsimport fra Paprika — genereret af scripts/paprika_import.py
do $import$
declare
  d jsonb := $json${"ingredients":[{"n":"Kardemomme","c":"Krydderier & smagsgivere","u":"tsk"},{"n":"Kærnemælk","c":"Mejeri & æg","u":"dl"},{"n":"Margarine","c":"Mejeri & æg","u":"g"},{"n":"Flormelis","c":"Kolonial","u":"g"},{"n":"Kakao","c":"Kolonial","u":"spsk"},{"n":"Radiser","c":"Frugt & grønt","u":"g"},{"n":"Rygeost","c":"Mejeri & æg","u":"g"},{"n":"Lammekød","c":"Kød & fisk","u":"g"},{"n":"Tahin","c":"Kolonial","u":"spsk"},{"n":"Sumak","c":"Krydderier & smagsgivere","u":"tsk"},{"n":"Ricotta","c":"Mejeri & æg","u":"g"},{"n":"Svinespæk","c":"Kød & fisk","u":"g"},{"n":"Pølsetarm","c":"Kød & fisk","u":null},{"n":"Pizzamel (tipo 00)","c":"Kolonial","u":"g"},{"n":"Durummel","c":"Kolonial","u":"g"},{"n":"Hvidvinseddike","c":"Kolonial","u":"spsk"},{"n":"Misopasta","c":"Krydderier & smagsgivere","u":"g"},{"n":"Pulled pork","c":"Kød & fisk","u":"g"},{"n":"Udonnudler","c":"Kolonial","u":"g"},{"n":"Østershatte","c":"Frugt & grønt","u":"g"},{"n":"Mandler","c":"Kolonial","u":"g"}],"tags":["Brød","Kage","Snacks","Tilbehør"],"recipes":[{"t":"Fødselsdagsboller","d":"Ca. 32 boller.","s":32,"tags":["Brød","Aldrig i ugeplan"],"i":[[null,200,"g","Smør",null],[null,5,"dl","Sødmælk",null],[null,50,"g","Gær",null],[null,1,"tsk","Salt","groft"],[null,140,"g","Sukker",null],[null,2,"stk","Æg",null],[null,1200,"g","Hvedemel","hold lidt igen – der er forskel på mel"],[null,2,"tsk","Kardemomme",null],[null,2,"stk","Æg","til pensling"]],"st":[[null,"Kom smør og mælk i en gryde. Varm det langsomt op, til smørret er næsten helt smeltet. Sluk for gryden og lad blandingen blive lunken (lillefingervarm). Det gør ikke noget, at lidt af smørret ikke er helt smeltet.",null],[null,"Kom blandingen i en skål (gerne røremaskine). Tilsæt gær og rør rundt.",null],[null,"Tilsæt salt, sukker og æg.",null],[null,"Tilsæt mel. Hold lidt igen – der kan være forskel på mel, så du skal måske bruge lidt mindre eller mere. Lad dejen køre på røremaskinen i cirka 10 minutter ved lav hastighed. Dejen skal være blank og smidig, men ikke klistre for meget. Lad dejen hæve i skålen med et viskestykke over i 60 minutter.",60],[null,"Form bollerne – cirka 70 g stykket. Tril dem på et bord (uden mel) og placér dem på en bageplade. Sæt et ildfast fad med kogende vand nederst i ovnen, og sæt bagepladen med boller ind, så de hæver med damp. Tænd ikke for ovnen. Lad dem hæve i 30 minutter.",30],[null,"Tag pladen med boller og fadet ud, og tænd ovnen på 210 grader (ikke varmluft).",null],[null,"Pensl bollerne. Når ovnen er varm (efter cirka 15 minutter), sættes bagepladen i midten af ovnen.",null],[null,"Bag i 10-12 minutter. Hold øje – der er forskel på ovne. Bank under bunden for at tjekke, at de er færdige; de skal lyde hule.",12]]},{"t":"Kanelkage","d":null,"s":4,"tags":["Kage","Aldrig i ugeplan"],"i":[["Dej",600,"g","Hvedemel",null],["Dej",500,"g","Sukker",null],["Dej",7,"dl","Kærnemælk",null],["Dej",3,"tsk","Natron",null],["Dej",175,"g","Margarine","smeltet"],["Dej",12,"tsk","Kanel","1 brev à 30 g"],["Glasur",175,"g","Margarine","smeltet"],["Glasur",350,"g","Flormelis",null],["Glasur",2,"spsk","Kakao",null],["Glasur",1,"stk","Æg",null]],"st":[[null,"Forvarm ovnen til 200 grader over-/undervarme.",null],[null,"Rør alle ingredienser til dejen sammen og hæld den i en stor bradepande (smurt eller med bagepapir).",null],[null,"Bag kagen i 30-40 minutter.",35],[null,"Pisk glasuren sammen og smør den på den afkølede kage.",null]]},{"t":"Kartoffelsalat med rygeost og radiser","d":null,"s":4,"tags":["Vegetar","Salat","Dansk"],"i":[[null,400,"g","Kartofler",null],[null,100,"g","Radiser",null],[null,300,"g","Spidskål",null],[null,50,"ml","Mayonnaise",null],[null,170,"g","Rygeost","100-170 g"],[null,1,"stk","Citron",null],[null,1,"stk","Rødløg",null],[null,0.5,"tsk","Sukker",null],[null,1,"spsk","Eddike",null],[null,null,null,"Salt",null],[null,null,null,"Peber",null]],"st":[[null,"Kog kartoflerne: Kog dem møre i let saltet vand – gerne tidligt på dagen eller aftenen før.",null],[null,"Sylt rødløg: Hak rødløget fint og kom det i en stor skål. Tilsæt saften fra citronen og ½ tsk sukker.",null],[null,"Forbered grøntsagerne: Skær spidskålen i mundrette stykker og radiserne i tynde skiver. Kom dem i en separat skål og krydr med salt og 1 spsk eddike. Vend godt sammen og lad det trække.",null],[null,"Rør dressingen: Kom mayonnaise og rygeost i skålen med rødløg og rør godt sammen.",null],[null,"Rør salaten: Skær kartoflerne i skiver og bland alle dele sammen. Smag til med salt og peber.",null]]},{"t":"Kebab à la Umut","d":"Opskrift fra Umut. Kebab og salsa laves gerne dagen forinden.","s":4,"tags":["Lam","Mellemøstlig"],"i":[["Kebab",1000,"g","Lammekød","filet eller culotte – svin eller okse kan også bruges"],["Kebab",1,"spsk","Paprika",null],["Kebab",1,"spsk","Spidskommen",null],["Kebab",1,"spsk","Peber",null],["Kebab",2,"fed","Hvidløg","finthakket"],["Kebab",10,"g","Salt",null],["Kebab",2,null,"Frisk timian","kviste"],["Fladbrød",400,"g","Hvedemel",null],["Fladbrød",10,"g","Salt",null],["Fladbrød",null,null,"Vand",null],["Chilisovs",2,"spsk","Tomatpuré",null],["Chilisovs",2,"spsk","Chiliflager",null],["Chilisovs",2,"tsk","Spidskommen",null],["Chilisovs",2,"tsk","Paprika",null],["Chilisovs",1,"tsk","Karry",null],["Chilisovs",1,"spsk","Soya",null],["Chilisovs",1,"spsk","Olivenolie",null],["Chilisovs",null,null,"Peber","en smule"],["Tahindressing",null,null,"Græsk yoghurt","1 del"],["Tahindressing",null,null,"Tahin","1 del"],["Tahindressing",null,null,"Salt",null],["Tomatsalsa",null,null,"Tomater",null],["Tomatsalsa",0.5,"stk","Rødløg",null],["Tomatsalsa",null,null,"Forårsløg",null],["Tomatsalsa",1,"stk","Peberfrugt","rød"],["Tomatsalsa",null,null,"Koriander",null],["Tomatsalsa",null,null,"Lime",null],["Tomatsalsa",null,null,"Citron",null],["Tomatsalsa",null,null,"Soya",null],["Tomatsalsa",2,"spsk","Tomatpuré",null],["Tomatsalsa",1,"fed","Hvidløg",null],["Løgsalat",0.5,"stk","Rødløg",null],["Løgsalat",null,null,"Forårsløg",null],["Løgsalat",null,null,"Persille",null],["Løgsalat",null,null,"Olivenolie",null],["Løgsalat",null,null,"Sumak",null],["Agurkesalat",1,"stk","Agurk",null],["Agurkesalat",null,null,"Dild",null],["Agurkesalat",4,"spsk","Creme fraiche","38 %"],["Agurkesalat",null,null,"Salt",null],["Spidskålssalat",1,"stk","Spidskål","hvidkål kan også bruges"],["Spidskålssalat",null,null,"Citron",null],["Spidskålssalat",null,null,"Olivenolie",null],["Spidskålssalat",null,null,"Salt",null]],"st":[["Kebab","Marineres gerne dagen før.",null],["Kebab","Pud kødet af for de værste sener og skær det i tynde stykker i passende størrelse. Fedt må gerne komme med.",null],["Kebab","Vend kødet med lidt olivenolie, salt, peber, paprika, spidskommen, finthakket frisk timian og finthakket hvidløg.",null],["Kebab","Lad kødet trække så længe som muligt, gerne fra dagen før.",null],["Kebab","Lynsteg kødet på en godt varm pande.",null],["Fladbrød","Bland mel og salt med vand til en passende konsistens.",null],["Fladbrød","Dæk dejen til og lad den hvile.",null],["Fladbrød","Rul dejen ud til tynde fladbrød.",null],["Fladbrød","Bag brødene på en tør, varm pande. De må gerne få lidt grillmærker.",null],["Tahindressing","Rør tahin og yoghurt sammen og smag til med salt.",null],["Chilisovs","Laves gerne dagen før. Rør alle ingredienser sammen til en chilisovs. Hvis sovsen har stået, kan olien skille – rør den bare sammen igen.",null],["Tomatsalsa","Laves gerne dagen før. Ønskes en meget fin salsa, kan alle ingredienser køres i foodprocessor.",null],["Tomatsalsa","Hak tomater, løg, forårsløg, peberfrugt, hvidløg og koriander så groft eller fint, som du ønsker salsaen.",null],["Tomatsalsa","Bland det hele med lidt soya, limesaft, lidt limeskal, citronsaft, lidt citronskal og tomatpuré.",null],["Tomatsalsa","Smag til med en smule salt.",null],["Løgsalat","Skær løg og forårsløg i tynde strimler, og hak persillen fint.",null],["Løgsalat","Bland med sumak, lidt olivenolie, citronsaft og en smule salt.",null],["Agurkesalat","Skær agurken i tynde skiver (nemt på foodprocessor). Salt skiverne ganske let og vend dem i saltet.",null],["Agurkesalat","Hak lidt dild fint og bland det i creme fraiche. Salt dressingen let.",null],["Agurkesalat","Pres vandet fra agurkeskiverne med et rent viskestykke, og vend skiverne i dressingen.",null],["Spidskålssalat","Hak spidskålen i fine strimler og marinér med lidt citronsaft.",null],["Spidskålssalat","Salt kålen ganske let og vend saltet rundt, så der trækker vand ud.",null],["Spidskålssalat","Når kålen er faldet sammen, presses væsken godt ud med et rent viskestykke. Vend kålen i lidt olivenolie, citronsaft og salt.",null],["Servering","Smør dressing i en stribe på fladbrødet, og læg de øvrige ingredienser på efter ønske. Servér rullet i bagepapir og sølvpapir.",null]]},{"t":"Medister","d":null,"s":4,"tags":["Svinekød","Dansk"],"i":[[null,1000,"g","Hakket svinekød","eller fx nakkefilet, du selv hakker"],[null,200,"g","Svinespæk","hakket"],[null,4,"dl","Fond","suppe kogt på svinekød/ben med porre, løg og gulerod (ikke selleri) – eller kraftig svinefond"],[null,null,null,"Pølsetarm",null],[null,null,null,"Salt",null],[null,null,null,"Peber",null]],"st":[[null,"Hak svinekødet 1½ gang, dvs. halvdelen køres gennem maskinen to gange. Kør gerne spækket igennem, hvis det er grofthakket.",null],[null,"Ælt kød og spæk sammen, og rør farsen sej med salt (ca. 15 g salt pr. kg kød).",null],[null,"Rør suppen i farsen – den skal være lind, men ikke alt for tynd. Smag til med salt og peber (2-3 g pr. kg kød).",null],[null,"Læg tarmen i blød i lunkent vand, og kør lidt vand igennem den, så den er \"åben\".",null],[null,"Sæt tarmen på pølsehornet og stop pølsen. Undgå luft så vidt muligt – tarmen kan prikkes med en nål, hvis det sker.",null],[null,"Kog pølsen 5-10 minutter. Kogevandet kan bruges til saucen.",10],[null,"Steg medisteren inden servering.",null]]},{"t":"Pizzadej","d":"To varianter: hurtig dej og langtidshævet dej. Vælg én af dem.","s":4,"tags":["Pizza","Italiensk"],"i":[["Hurtig dej",2.5,"dl","Vand","lunkent"],["Hurtig dej",0.75,"tsk","Salt","fint havsalt"],["Hurtig dej",15,"g","Gær",null],["Hurtig dej",1,"knsp","Sukker",null],["Hurtig dej",null,null,"Citron","3-4 dråber saft"],["Hurtig dej",400,"g","Pizzamel (tipo 00)",null],["Hurtig dej",null,null,"Hvedemel","til udrulning"],["Langtidshævet dej",350,"g","Pizzamel (tipo 00)",null],["Langtidshævet dej",50,"g","Durummel","fint"],["Langtidshævet dej",2.5,"dl","Vand","lunkent"],["Langtidshævet dej",10,"g","Gær","8-10 g"],["Langtidshævet dej",1.75,"tsk","Salt","fint havsalt"],["Langtidshævet dej",null,null,"Hvedemel","til udrulning"]],"st":[["Hurtig dej","Rør vand, salt, gær, sukker og citronsaft sammen.",null],["Hurtig dej","Tilsæt melet lidt ad gangen.",null],["Hurtig dej","Ælt dejen omhyggeligt og længe, til den er blank og elastisk.",null],["Hurtig dej","Dæk skålen med plastfilm og lad dejen hæve til mindst dobbelt størrelse på et lunt sted (2-3 timer).",150],["Hurtig dej","Slå dejen ned, del den i portioner og form dem til kugler. Vend dem i mel og lad dem efterhæve på køkkenbordet i 15-30 minutter.",20],["Hurtig dej","Tænd ovnen på maks. almindelig over-/undervarme, helst 275 grader – gerne 300. Drys mel på bordet og rul en dejkugle ud til en stor, ca. 3-4 mm tynd bund. Den behøver ikke være rund, bare den kan være på en bageplade.",null],["Hurtig dej","Rul bunden let om kagerullen og flyt den over på bagepapir. Gør det samme med den anden portion – så er bundene klar til fyld.",null],["Langtidshævet dej","Vej de to slags mel af hver for sig.",null],["Langtidshævet dej","Rør ½ dl af vandet, salt og gær med 4 spsk af hvedemelet (tipo 00) til en fordej med jævn pastakonsistens.",null],["Langtidshævet dej","Dæk fordejen med plastfilm og lad den hæve til dobbelt størrelse på et lunt sted (ca. 40 minutter).",40],["Langtidshævet dej","Rør resten af hvedemelet, durummelet og vandet i fordejen, og ælt omhyggeligt, til dejen er blank og elastisk.",null],["Langtidshævet dej","Dæk skålen med plastfilm og lad dejen hæve langsomt et køligt sted (5-10 grader) i 12-18 timer.",null],["Langtidshævet dej","Slå dejen ned og lad den efterhæve – så er den klar til at blive rullet ud og få fyld på.",null]]},{"t":"Pulled pork-ramen","d":null,"s":2,"tags":["Svinekød","Asiatisk","Suppe"],"i":[["Syltede gulerødder",1,"stk","Gulerod",null],["Syltede gulerødder",15,"ml","Hvidvinseddike",null],["Syltede gulerødder",0.5,"tsk","Sukker",null],["Syltede gulerødder",1,"spsk","Vand",null],["Misosuppe",300,"g","Pulled pork",null],["Misosuppe",1,"fed","Hvidløg",null],["Misosuppe",2,"tsk","Ingefær","revet"],["Misosuppe",50,"g","Misopasta",null],["Misosuppe",10,"ml","Fiskesauce",null],["Misosuppe",0.5,"l","Hønsebouillon","kyllingebouillon"],["Misosuppe",25,"ml","Soya",null],["Misosuppe",1,"tsk","Sukker",null],["Misosuppe",0.5,"stk","Lime",null],["Nudler",150,"g","Udonnudler",null],["Topping",200,"g","Østershatte",null],["Topping",null,null,"Sukkerærter",null],["Topping",1,"stk","Chili","rød"],["Topping",2,"stk","Forårsløg",null]],"st":[["Syltede gulerødder","Skær guleroden i tynde stave.",null],["Syltede gulerødder","Bland hvidvinseddike, sukker, vand og et nip salt, og vend guleroden i lagen. Hæld lagen fra inden servering.",null],["Stegte svampe","Hak svampene groft. Varm lidt olie op i en gryde ved høj varme og steg svampene i 3-4 minutter.",4],["Stegte svampe","Krydr med salt og peber, og læg dem over på en tallerken.",null],["Misosuppe","Sæt samme gryde på middelhøj varme. Riv ingefær fint og pres hvidløg.",null],["Misosuppe","Kom svinekød (inkl. væsken fra pakken), kyllingebouillon, ingefær, hvidløg, misopasta, sojasauce, sukker og fiskesauce i gryden. Lad det simre 10-12 minutter under låg.",12],["Misosuppe","Træk kødet fra hinanden med to gafler i gryden.",null],["Nudler","Bring saltet vand i kog i en anden gryde og kog nudlerne efter anvisningen.",null],["Nudler","Tilsæt nudler og limesaft til misosuppen lige inden servering, og vend sammen.",null],["Topping","Halvér sukkerærterne på langs. Flæk chilien, fjern kernerne og skær den i tynde skiver.",null],["Servering","Anret nudlerne i dybe skåle. Top med pulled pork, svampe, sukkerærter og gulerod, og drys med forårsløg og chili.",null]]},{"t":"Pølsehorn","d":"32 stk.","s":32,"tags":["Brød","Aldrig i ugeplan"],"i":[[null,25,"g","Gær",null],[null,3,"dl","Sødmælk",null],[null,100,"g","Smør",null],[null,1,"tsk","Salt",null],[null,1,"tsk","Sukker",null],[null,1,"stk","Æg",null],[null,600,"g","Hvedemel",null],[null,32,"stk","Pølser",null],[null,1,"stk","Æg","til pensling"]],"st":[[null,"Lun mælken og rør gæren ud heri.",null],[null,"Smuldr smørret i melet med fingrene, til det ligner revet ost.",null],[null,"Tilsæt mælken med gær, salt, sukker og æg, og ælt dejen glat og smidig. Lad den hæve overdækket i 1 time.",60],[null,"Ælt dejen let igennem og del den i 4 lige store stykker. Rul hvert stykke ud til en cirkel og skær den i 8 trekanter (32 i alt).",null],[null,"Læg en pølse på hver trekant og rul hornet.",null],[null,"Lad hornene efterhæve i 30 minutter. Pensl med æg og bag dem 15-20 minutter i en forvarmet ovn ved 200 grader (alm. ovn).",30]]},{"t":"Saltede mandler","d":null,"s":4,"tags":["Snacks","Aldrig i ugeplan"],"i":[[null,7,"spsk","Salt","groft"],[null,4,"dl","Vand",null],[null,400,"g","Mandler",null],[null,null,null,"Olivenolie",null],[null,null,null,"Salt","groft"]],"st":[[null,"Kog vandet op med salt, til saltet er opløst.",null],[null,"Tilsæt mandlerne og sluk for varmen. Lad mandlerne trække i 20 minutter.",20],[null,"Dryp mandlerne af, vend dem i olie og groft salt, og læg dem på bagepapir.",null],[null,"Bag dem i ovnen ved 180 grader i 10-12 minutter. Vend dem undervejs.",12]]},{"t":"Tomatsalsa","d":"Laves gerne dagen før.","s":4,"tags":["Tilbehør","Aldrig i ugeplan"],"i":[[null,null,null,"Tomater",null],[null,null,null,"Rødløg",null],[null,null,null,"Forårsløg",null],[null,null,null,"Peberfrugt","rød"],[null,null,null,"Koriander",null],[null,null,null,"Lime",null],[null,null,null,"Citron",null],[null,null,null,"Soya",null],[null,null,null,"Tomatpuré",null],[null,null,null,"Hvidløg",null]],"st":[[null,"Ønskes en meget fin salsa, kan alle ingredienser blot køres i foodprocessor.",null],[null,"Hak tomater, løg, forårsløg, peberfrugt, hvidløg og koriander så groft eller fint, som du ønsker salsaen.",null],[null,"Bland det hele med lidt soya, limesaft, lidt limeskal, citronsaft, lidt citronskal og tomatpuré.",null],[null,"Smag til med en smule salt.",null]]}]}$json$::jsonb;
  ing jsonb; rec jsonb; item jsonb; t text; rid uuid; iid uuid; idx int; missing text;
  owner uuid := (select id from auth.users where lower(email) = 'mortenrose@protonmail.com');
begin
  -- Nye ingredienser
  for ing in select * from jsonb_array_elements(d->'ingredients') loop
    insert into madplan.ingredients (name, category_id, default_unit)
    select ing->>'n', (select id from madplan.shop_categories where name = ing->>'c'), ing->>'u'
    where not exists (select 1 from madplan.ingredients where lower(name) = lower(ing->>'n'));
  end loop;

  -- Vand skal ikke på indkøbslisten: basisvare der altid er "på lager"
  update madplan.ingredients set is_staple = true, in_stock = true where lower(name) = 'vand';

  -- Nye tags i gruppen "Type"
  for t in select * from jsonb_array_elements_text(d->'tags') loop
    insert into madplan.tags (name, group_id, sort_order)
    select t, (select id from madplan.tag_groups where name = 'Type'), 100
    where not exists (select 1 from madplan.tags where lower(name) = lower(t));
  end loop;

  -- Tjek at alle ingredienser og tags findes, før noget oprettes
  select string_agg(distinct x->>3, ', ') into missing
  from jsonb_array_elements(d->'recipes') r, jsonb_array_elements(r->'i') x
  where not exists (select 1 from madplan.ingredients i where lower(i.name) = lower(x->>3));
  if missing is not null then raise exception 'Mangler ingredienser: %', missing; end if;

  select string_agg(distinct x, ', ') into missing
  from jsonb_array_elements(d->'recipes') r, jsonb_array_elements_text(r->'tags') x
  where not exists (select 1 from madplan.tags tg where lower(tg.name) = lower(x));
  if missing is not null then raise exception 'Mangler tags: %', missing; end if;

  -- Opskrifter (springes over, hvis titlen allerede findes)
  for rec in select * from jsonb_array_elements(d->'recipes') loop
    if exists (select 1 from madplan.recipes where lower(title) = lower(rec->>'t')) then
      raise notice 'Springer over: %', rec->>'t';
      continue;
    end if;

    insert into madplan.recipes (title, description, servings, created_by)
    values (rec->>'t', rec->>'d', (rec->>'s')::int, owner)
    returning id into rid;

    idx := 0;
    for item in select * from jsonb_array_elements(rec->'i') loop
      select id into iid from madplan.ingredients where lower(name) = lower(item->>3);
      insert into madplan.recipe_ingredients (recipe_id, ingredient_id, amount, unit, note, section, sort_order)
      values (rid, iid, (item->>1)::numeric, item->>2, item->>4, item->>0, idx);
      idx := idx + 1;
    end loop;

    idx := 0;
    for item in select * from jsonb_array_elements(rec->'st') loop
      insert into madplan.recipe_steps (recipe_id, text, timer_minutes, section, sort_order)
      values (rid, item->>1, (item->>2)::int, item->>0, idx);
      idx := idx + 1;
    end loop;

    insert into madplan.recipe_tags (recipe_id, tag_id)
    select rid, tg.id from madplan.tags tg
    where lower(tg.name) in (select lower(x) from jsonb_array_elements_text(rec->'tags') x);
  end loop;
end
$import$;

